cat >> docs/notes/BKG-12.md <<'EOF'

## テストリスト（層）
1. 終わり=始まりの隣接は重ならない（両側）— slots.spec.sh、小（overlaps の純粋な計算、境界値）
2. 部分重複・包含・同一区間は重なる — slots.spec.sh、小（二重予約防止の維持。同一区間は新規）
3. チケットの再現: 10:00-11:00 の後の 11:00-12:00 が booked、重なりは conflict — spec/book.spec.sh、中（一時 BOOKINGS で book.sh を実行）
書かない: to_min の追加テスト（既存で足りる）、data/ を使うテスト（本番の記録に触れない）。
EOF
cat >> spec/slots.spec.sh.new <<'EOF'
EOF
rm spec/slots.spec.sh.new
python3 - <<'EOF'
p='spec/slots.spec.sh'
s=open(p).read()
s=s.replace("[ \"$(to_min 09:05)\"","""! overlaps 600 660 660 720 || { echo "adjacent: 10:00-11:00 then 11:00-12:00"; fail=1; }
! overlaps 660 720 600 660 || { echo "adjacent: 11:00-12:00 after 10:00-11:00"; fail=1; }
overlaps 600 660 600 660 || { echo "overlap: identical"; fail=1; }
[ "$(to_min 09:05)\"""",1)
open(p,'w').write(s)
EOF
cat > spec/book.spec.sh <<'EOF'
#!/bin/bash
# book.sh against a temporary bookings file (never data/).
fail=0
export BOOKINGS=$(mktemp); trap 'rm -f "$BOOKINGS"' EXIT
book() { bash src/book.sh aoi 2026-11-12 "$@" >/dev/null 2>&1; }
book 10:00 11:00 sato || { echo "first booking"; fail=1; }
book 11:00 12:00 ito || { echo "adjacent after must book"; fail=1; }
book 09:00 10:00 kato || { echo "adjacent before must book"; fail=1; }
! book 10:30 11:30 y || { echo "partial overlap must conflict"; fail=1; }
! book 10:00 11:00 z || { echo "identical must conflict"; fail=1; }
[ "$(grep -vc '^#' "$BOOKINGS")" = 3 ] || { echo "expected 3 bookings"; fail=1; }
exit $fail
EOF
bash tools/check

